package dev.raf.radar;
import android.content.Context;import android.view.*;import android.widget.*;import androidx.test.core.app.ActivityScenario;import androidx.test.platform.app.InstrumentationRegistry;import org.json.*;import org.junit.Test;import static org.junit.Assert.*;
public class SettingsPolishTest {
 static boolean contains(View v,String text){if(v instanceof TextView&&((TextView)v).getText().toString().equals(text))return true;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)if(contains(((ViewGroup)v).getChildAt(i),text))return true;return false;}
 @Test public void compactProfileCleanSettingsAndRefresh()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();Store s=new Store(c);s.prefs.edit().clear().putBoolean("autoUpdate",false).putBoolean("sounds",false).commit();AccountClient.save(s,new JSONObject().put("user",new JSONObject().put("id",999).put("name","Bo@@ss")).put("session","a".repeat(64)));ScreenTest.grantAccess();
 try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(MainActivity.class)){scenario.onActivity(a->{View settings=a.settingsContents();assertTrue(contains(settings,"Имя: Bo@@ss"));assertTrue(contains(settings,"ID: 999"));assertTrue(contains(settings,"Звук"));assertFalse(contains(settings,"Звуки"));assertFalse(contains(settings,"Диагностика"));assertFalse(contains(settings,"Удалить последнюю геопозицию"));a.directoryPending=true;a.showFriends();assertNotNull(a.friendsDialog.getButton(-3).getCompoundDrawables()[0]);assertTrue(a.friendsRefreshIcon.spin.isRunning());a.directoryPending=false;a.renderFriends();assertNull(a.friendsRefreshIcon.spin);});ScreenTest.capture("settings-polish");}finally{AccountClient.clear(s);}}
}
